@n5 syntax.nominal head="240"
@r2 syntax.relation from=$n1 to=$c2
@r3 syntax.relation from=$n1 to=$c3
@r4 syntax.relation from=$n4 to=$n5

sop:
@c1 syntax.clause form=imperative verb="update" complement=$n1
@n1 syntax.nominal dependent="arrow" head="a1"
@c2 syntax.clause form=nonfinite verb="labelled" modifier="next"
@c3 syntax.clause form=nonfinite verb="coloured" complement=$n2
@n2 syntax.nominal head="blue"
@r1 syntax.relation from=$n1 to=$c2
@r2 syntax.relation from=$c2 to=$c3

alt:
@c1 syntax.clause form=imperative verb="update" complement=$n1
@n1 syntax.nominal head="arrow" dependent="a1"
@c2 syntax.clause form=nonfinite verb="labelled" modifier="next"
@c3 syntax.clause form=nonfinite verb="coloured" complement=$n2
@n2 syntax.nominal head="blue"
@r1 syntax.relation from=$n1 to=$c2
@r2 syntax.relation from=$n1 to=$c3
